package mz.bam.seeky.android;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.text.TextUtils;
import android.view.*;
import android.widget.*;

/** Compact native sheets with constrained scrolling, rounded surfaces and visible actions. */
final class UiPanel {
 static final java.util.Map<Activity,java.util.Set<UiPanel>> open=new java.util.HashMap<>();
 static void visibility(Activity host,boolean visible){java.util.Set<UiPanel> panels=open.get(host);if(panels!=null)for(UiPanel p:new java.util.ArrayList<>(panels))QuickSearchService.holdOverlay(p.hold,visible&&p.dialog.isShowing());}
 static void dismissAll(Activity host){java.util.Set<UiPanel> panels=open.remove(host);if(panels!=null)for(UiPanel panel:new java.util.ArrayList<>(panels))panel.dialog.dismiss();}
 Runnable dismissed;final Activity host;final Dialog dialog;final LinearLayout root,content;final int surface,ink,muted,accent,bg;final String hold="panel-"+java.util.UUID.randomUUID();
 int dp(float n){return (int)(n*host.getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 TextView text(String s,int size,int color){TextView t=new TextView(host);t.setText(AppLanguage.text(host,s));t.setTextSize(size);t.setTextColor(color);return t;}
 UiPanel(Activity host,String title,String subtitle,String symbol){
  this.host=host;AppPalette palette=AppPalette.of(host);surface=palette.surface;ink=palette.ink;muted=palette.muted;accent=palette.accent;bg=palette.tint;
  dialog=new Dialog(host);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);root=new LinearLayout(host);root.setOrientation(1);GradientDrawable shell=shape(surface,24);shell.setStroke(dp(1),palette.line);root.setBackground(new BrandSurface(host,BrandSurface.SHEET));root.setClipToOutline(true);root.setPadding(dp(16),dp(10),dp(16),dp(12));
  View handle=new View(host);handle.setBackground(shape((muted&0xffffff)|0x55000000,3));LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(dp(34),dp(4));hp.gravity=Gravity.CENTER;hp.bottomMargin=dp(16);root.addView(handle,hp);
  LinearLayout head=new LinearLayout(host);head.setGravity(Gravity.CENTER_VERTICAL);FrameLayout tile=new FrameLayout(host);GradientDrawable tileFill=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{ThemeColors.blend(accent,Color.WHITE,.18f),accent});tileFill.setCornerRadius(dp(16));tile.setBackground(tileFill);tile.addView(new Icons(host,symbol,AppPalette.of(host).onAccent),new FrameLayout.LayoutParams(dp(26),dp(26),Gravity.CENTER));head.addView(tile,new LinearLayout.LayoutParams(dp(50),dp(50)));LinearLayout captions=new LinearLayout(host);captions.setOrientation(1);captions.setPadding(dp(12),0,dp(8),0);TextView label=text(title,20,ink);label.setTypeface(null,Typeface.BOLD);label.setMaxLines(2);label.setEllipsize(TextUtils.TruncateAt.MIDDLE);captions.addView(label);if(subtitle!=null&&!subtitle.isEmpty()){TextView sub=text(subtitle,11,muted);sub.setMaxLines(2);sub.setEllipsize(TextUtils.TruncateAt.MIDDLE);captions.addView(sub);}head.addView(captions,new LinearLayout.LayoutParams(0,-2,1));TextView close=text("×",27,muted);close.setGravity(Gravity.CENTER);close.setContentDescription(AppLanguage.text(close.getContext(),"Fechar menu"));close.setOnClickListener(v->dialog.dismiss());close.setBackground(shape(bg,22));head.addView(close,new LinearLayout.LayoutParams(dp(44),dp(44)));root.addView(head);
  ScrollView scroll=new ScrollView(host);scroll.setFillViewport(false);scroll.setClipToPadding(false);content=new LinearLayout(host);content.setOrientation(1);content.setPadding(0,dp(14),0,dp(4));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));dialog.setContentView(root);
  dialog.setOnShowListener(d->{QuickSearchService.holdOverlay(hold,true);Motion.enter(root,0);});dialog.setOnDismissListener(d->{QuickSearchService.holdOverlay(hold,false);java.util.Set<UiPanel> panels=open.get(host);if(panels!=null){panels.remove(this);if(panels.isEmpty())open.remove(host);}if(dismissed!=null)dismissed.run();});
 }
 void section(String title){TextView label=text(title.toUpperCase(java.util.Locale.ROOT),10,muted);label.setLetterSpacing(.1f);label.setPadding(dp(3),dp(15),0,dp(6));content.addView(label);}
 void note(String message){TextView t=text(message,13,muted);t.setPadding(dp(3),dp(7),dp(3),dp(10));content.addView(t);}
 void action(String symbol,String title,String subtitle,boolean danger,Runnable task){LinearLayout row=new LinearLayout(host);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(10),dp(10),dp(10));row.setElevation(dp(1));GradientDrawable tileShape=shape(surface,15);tileShape.setStroke(dp(1),AppPalette.of(host).line);row.setBackground(tileShape);int color=danger?0xffbd435c:accent;FrameLayout iconTile=new FrameLayout(host);int iconColor=symbol.equals("settings")||symbol.equals("book")?0xffc53b43:color;iconTile.setBackground(shape(ThemeColors.blend(surface,iconColor,.09f),13));iconTile.addView(new Icons(host,symbol,iconColor),new FrameLayout.LayoutParams(dp(26),dp(26),Gravity.CENTER));row.addView(iconTile,new LinearLayout.LayoutParams(dp(40),dp(40)));LinearLayout copy=new LinearLayout(host);copy.setOrientation(1);copy.setPadding(dp(12),0,dp(6),0);TextView heading=text(title,14,danger?color:ink);heading.setTypeface(null,Typeface.BOLD);copy.addView(heading);if(subtitle!=null&&!subtitle.isEmpty()){TextView sub=text(subtitle,11,muted);sub.setMaxLines(2);copy.addView(sub);}row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));row.addView(new Icons(host,"chevron",accent),new LinearLayout.LayoutParams(dp(17),dp(20)));row.setContentDescription(title+(subtitle==null?"":". "+subtitle));row.setOnClickListener(v->{dialog.dismiss();task.run();});Motion.touch(row);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(7);content.addView(row,lp);}
 void primary(String first,String second,Runnable open,Runnable preview){LinearLayout row=new LinearLayout(host);TextView a=text(first,14,Color.WHITE),b=text(second,14,accent);a.setTypeface(null,Typeface.BOLD);b.setTypeface(null,Typeface.BOLD);a.setBackground(shape(accent,15));a.setTextColor(AppPalette.of(host).onAccent);b.setBackground(shape(bg,15));a.setGravity(Gravity.CENTER);b.setGravity(Gravity.CENTER);a.setOnClickListener(v->{dialog.dismiss();open.run();});b.setOnClickListener(v->{dialog.dismiss();preview.run();});Motion.touch(a);Motion.touch(b);LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,dp(49),1);left.rightMargin=dp(12);row.addView(a,left);row.addView(b,new LinearLayout.LayoutParams(0,dp(49),1));LinearLayout.LayoutParams pair=new LinearLayout.LayoutParams(-1,-2);pair.bottomMargin=dp(12);content.addView(row,pair);}
 void quick(String[] symbols,String[] titles,Runnable[] actions){LinearLayout strip=new LinearLayout(host);for(int i=0;i<titles.length;i++){final Runnable action=actions[i];LinearLayout item=new LinearLayout(host);item.setOrientation(1);item.setGravity(Gravity.CENTER);item.addView(new Icons(host,symbols[i],accent),new LinearLayout.LayoutParams(dp(23),dp(23)));TextView caption=text(titles[i],11,ink);caption.setGravity(Gravity.CENTER);caption.setPadding(0,dp(6),0,0);item.addView(caption);item.setContentDescription(titles[i]);item.setOnClickListener(v->{dialog.dismiss();action.run();});Motion.touch(item);strip.addView(item,new LinearLayout.LayoutParams(0,dp(70),1));}content.addView(strip);}
 void danger(String title,Runnable action){TextView delete=text(title,14,0xffb93d56);delete.setGravity(Gravity.CENTER);delete.setTypeface(null,Typeface.BOLD);delete.setBackground(shape((0xffb93d56&0xffffff)|0x10000000,14));delete.setOnClickListener(v->{dialog.dismiss();action.run();});Motion.touch(delete);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(48));lp.topMargin=dp(8);root.addView(delete,lp);}
 void show(){UiSpacing.watch(root);if(host.isFinishing()||host.isDestroyed())return;open.computeIfAbsent(host,h->new java.util.HashSet<>()).add(this);dialog.show();Window w=dialog.getWindow();if(w==null)return;w.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams p=w.getAttributes();p.dimAmount=.32f;p.gravity=Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL;p.width=Math.min(host.getResources().getDisplayMetrics().widthPixels-dp(24),dp(520));content.measure(View.MeasureSpec.makeMeasureSpec(Math.max(1,p.width-dp(32)),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));int desired=content.getMeasuredHeight()+dp(root.getChildCount()>3?190:135);p.height=Math.min(Math.max(dp(250),desired),Math.min((int)(host.getResources().getDisplayMetrics().heightPixels*.82f),dp(720)));p.y=dp(14);w.setAttributes(p);}
}
